      source: attacker,
      target: defender,
      item: weaponId,
      damage: dmg,
      damageType,
      crit: isCrit,
      scratch: procScratch,
      tags: ['ranged', 'projectile', `relation:${positional.relation}`],
    }), { excludeSlots: ['weapon'] });

    // Ammo coating (e.g. paralysis-coated arrows)
    applyWeaponCoatingOnHit(world, {
      attacker, defender, weaponId: ammoId,
      didHit: dmg > 0,
    });

    // Apply damage through canonical pipeline
    const result = dealDamage(world, {
      target: defender,
      amount: dmg,
      source: attacker,
      type: damageType,
      cause: 'ranged',
      critical: isCrit,
      armorPenetration,
